package com.andye.warmod.phalanx.client;import com.andye.warmod.phalanx.network.*;import java.util.*;import net.minecraft.world.phys.Vec3;
public final class PhalanxTracerManager{public record Tracer(UUID id,Vec3 origin,Vec3 velocity,long seed,long startTime){}private static final Map<UUID,Tracer> ACTIVE=new LinkedHashMap<>();private PhalanxTracerManager(){}public static synchronized void shot(ClientboundPhalanxShotPayload p,long time){while(ACTIVE.size()>=4096)ACTIVE.remove(ACTIVE.keySet().iterator().next());ACTIVE.put(p.shotId(),new Tracer(p.shotId(),p.origin(),p.velocity(),p.visualSeed(),time));}public static synchronized void impact(UUID id){ACTIVE.remove(id);}public static synchronized List<Tracer> snapshot(long now){ACTIVE.values().removeIf(t->now-t.startTime()>30);return List.copyOf(ACTIVE.values());}public static synchronized void clear(){ACTIVE.clear();}}
